'use strict'

const { createServer } = require('node:http')
const { once } = require('node:events')
const { Client, interceptors } = require('.')

async function main () {
  let counter = 0
  const server = createServer({ joinDuplicateHeaders: true }, (req, res) => {
    counter++
    if (counter < 3) {
      res.writeHead(500, { 'content-type': 'text/plain', connection: 'close' })
      res.end('failure')
      return
    }
    res.writeHead(200, { 'content-type': 'text/plain' })
    res.end('hello world!')
  })
  server.listen(0)
  await once(server, 'listening')

  const client = new Client(`http://localhost:${server.address().port}`)
    .compose(interceptors.retry({ maxRetries: 3, minTimeout: 50, maxTimeout: 50, timeoutFactor: 1, throwOnError: false }))

  const timer = setTimeout(() => {
    console.log('TIMED OUT -- retry never advanced. attempts:', counter)
    process.exit(1)
  }, 4000)

  const res = await client.request({ method: 'GET', path: '/' })
  console.log('statusCode', res.statusCode)
  console.log('body', JSON.stringify(await res.body.text()))
  clearTimeout(timer)
  await client.close()
  server.close()
  await once(server, 'close')
}

main().catch(err => { console.error('ERR', err); process.exit(1) })

