'use strict'

const RetryHandler = require('./lib/handler/retry-handler')

for (const m of ['onRequestStart', 'onResponseStart', 'onResponseData', 'onResponseEnd', 'onResponseError', 'retry']) {
  const orig = RetryHandler.prototype[m]
  RetryHandler.prototype[m] = function (...args) {
    const extra = m === 'onResponseData' ? JSON.stringify(args[1]?.toString()) : (m === 'onResponseStart' ? args[1] : (args[1]?.message ?? ''))
    console.log(`  [RH] ${m}`, extra, 'headersSent=', this.headersSent, 'retryPending=', this.retryPending, 'error=', this.error?.message)
    return orig.apply(this, args)
  }
}

const net = require('node:net')
const { once } = require('node:events')
const { Client, interceptors } = require('.')

// variant: 'empty' -> 500 with content-length: 0 ; 'split' -> body sent in a later packet
const variant = process.argv[2] ?? 'empty'

async function main () {
  let counter = 0
  const server = net.createServer(socket => {
    socket.on('error', () => {})
    socket.once('data', () => {
      counter++
      console.log('[server] request', counter, 'variant', variant)
      if (counter < 3) {
        if (variant === 'empty') {
          socket.end('HTTP/1.1 500 Internal Server Error\r\nContent-Type: text/plain\r\nConnection: close\r\nContent-Length: 0\r\n\r\n')
        } else {
          socket.write('HTTP/1.1 500 Internal Server Error\r\nContent-Type: text/plain\r\nConnection: close\r\nContent-Length: 7\r\n\r\n')
          setTimeout(() => socket.end('failure'), 20)
        }
        return
      }
      socket.end('HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\nContent-Length: 12\r\nConnection: close\r\n\r\nhello world!')
    })
  })
  server.listen(0)
  await once(server, 'listening')

  const client = new Client(`http://localhost:${server.address().port}`)
    .compose(interceptors.retry({ maxRetries: 3, minTimeout: 100, maxTimeout: 100, timeoutFactor: 1, throwOnError: false }))

  const timer = setTimeout(() => {
    console.log('TIMED OUT -- retry never advanced. attempts:', counter)
    process.exit(1)
  }, 4000)

  try {
    const res = await client.request({ method: 'GET', path: '/' })
    console.log('statusCode', res.statusCode)
    console.log('body', JSON.stringify(await res.body.text()))
  } catch (err) {
    console.log('REQUEST REJECTED', err.code, err.message)
  }
  clearTimeout(timer)
  await client.close()
  server.close()
  await once(server, 'close')
}

main().catch(err => { console.error('ERR', err); process.exit(1) })

