      retry: (err, { state, opts }, done) => {
        counter++

        if (
          err.statusCode === 500 ||
          err.message.includes('other side closed')
        ) {
          setTimeout(done, 500)
          return
        }

        return done(err)
      }
    }
  }

  server.on('request', (req, res) => {
    switch (counter) {
      case 0:
        req.destroy()
        return
      case 1:
        res.writeHead(500)
        res.end('failed')
        return
      case 2:
        res.writeHead(200)
        res.end('hello world!')
        return
      default:
        t.fail()
    }
  })

  server.listen(0)

  await once(server, 'listening')
  const client = new Client(
    `http://localhost:${server.address().port}`
  ).compose(retry())

  after(async () => {
    await client.close()
    server.close()

    await once(server, 'close')
  })

  const response = await client.request(requestOptions)
  t.equal(response.statusCode, 200)
  t.equal(await response.body.text(), 'hello world!')
})

test('should not error if request is not meant to be retried', async t => {
  t = tspl(t, { plan: 2 })

  const server = createServer({ joinDuplicateHeaders: true })
  server.on('request', (req, res) => {
    res.writeHead(400)
    res.end('Bad request')
  })

  server.listen(0)

  await once(server, 'listening')

  const client = new Client(
    `http://localhost:${server.address().port}`
  ).compose(retry())

  after(async () => {
    await client.close()
    server.close()

    await once(server, 'close')
  })

  const response = await client.request({
    method: 'GET',
    path: '/',
    headers: {
      'content-type': 'application/json'
    }
  })

  t.equal(response.statusCode, 400)
  t.equal(await response.body.text(), 'Bad request')
})

test('should reject the original response body when a retry returns a non-retryable status', async t => {
  t = tspl(t, { plan: 3 })

  let count = 0
  const server = createServer({ joinDuplicateHeaders: true }, (req, res) => {
    count++

    if (count === 1) {
      res.setHeader('content-length', '5')
      res.write('123', () => res.destroy())
      return
    }

    if (count === 2) {
      res.writeHead(400)
      res.end()
      return
    }

    t.fail('unexpected request')
  })

  server.listen(0)
  await once(server, 'listening')

  const client = new Client(
    `http://localhost:${server.address().port}`,
    { bodyTimeout: 100 }
  ).compose(retry({ minTimeout: 10 }))

  after(async () => {
    await client.close()
    server.close()
    await once(server, 'close')
  })

  const response = await client.request({
    method: 'GET',
    path: '/'
  })

  t.strictEqual(response.statusCode, 200)

  let timer
  let bodyError
  try {
    bodyError = await Promise.race([
      response.body.text().then(() => null, err => err),
      new Promise(resolve => {
        timer = setTimeout(() => resolve(new Error('response body timed out')), 2e3)
      })
    ])
  } finally {
    clearTimeout(timer)
    response.body.destroy()
  }

  t.strictEqual(bodyError?.code, 'UND_ERR_REQ_RETRY')
  t.strictEqual(count, 2)
})

// An empty body plus `connection: close`, flushed together with the FIN, makes
// the response end while the retry policy is still deciding: the parser has
// nothing left to buffer, so the EOF completes the message across the paused
// controller. A raw socket is what keeps that framing exact.
function closingRetryServer (shouldSucceed) {
  return createNetServer(socket => {
    socket.on('error', () => {})
    socket.once('data', chunk => {
      const path = chunk.toString().split(' ')[1]

      if (!shouldSucceed(path)) {
        socket.end('HTTP/1.1 500 Internal Server Error\r\nConnection: close\r\nContent-Length: 0\r\n\r\n')
        return
      }

      const body = `hello ${path}`
      socket.end(
        'HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\nConnection: close\r\n' +
        `Content-Length: ${body.length}\r\n\r\n${body}`
      )
    })
  })
}

function withDeadline (promise, message) {
  let timer
  return Promise.race([
    promise.finally(() => clearTimeout(timer)),
    new Promise((_resolve, reject) => {
      timer = setTimeout(() => reject(new Error(message)), 10e3)
    })
  ])
}

test('Should retry concurrent responses that end after the connection is closed', async t => {
  t = tspl(t, { plan: 7 })

  const attempts = new Map()
  const server = closingRetryServer(req => {
    const count = (attempts.get(req.url) ?? 0) + 1
    attempts.set(req.url, count)
    return count === 3
  })

  server.listen(0)
  await once(server, 'listening')

  const client = new Client(
    `http://localhost:${server.address().port}`
  ).compose(retry({ minTimeout: 10, maxTimeout: 10, timeoutFactor: 1, throwOnError: false }))

  after(async () => {
    await client.close()
    server.close()
    await once(server, 'close')
  })

  const paths = ['/a', '/b', '/c']
  const responses = await withDeadline(
    Promise.all(paths.map(path => client.request({ method: 'GET', path }))),
    'retry did not advance after the connection was closed'
  )

  for (let i = 0; i < paths.length; i++) {
    t.strictEqual(responses[i].statusCode, 200)
    t.strictEqual(
      await withDeadline(responses[i].body.text(), 'response body never settled'),
      `hello ${paths[i]}`
    )
  }

  t.deepStrictEqual([...attempts.values()], [3, 3, 3])
})

test('Should expose the last closing response once retries are exhausted', async t => {
  t = tspl(t, { plan: 3 })

  let count = 0
  const server = closingRetryServer(() => {
    count++
    return false
  })

  server.listen(0)
  await once(server, 'listening')

  const client = new Client(
    `http://localhost:${server.address().port}`
  ).compose(retry({ maxRetries: 2, minTimeout: 10, maxTimeout: 10, timeoutFactor: 1, throwOnError: false }))

  after(async () => {
    await client.close()
    server.close()
    await once(server, 'close')
  })

  const response = await withDeadline(
    client.request({ method: 'GET', path: '/' }),
    'exhausted retry never settled'
  )

  t.strictEqual(response.statusCode, 500)
  t.strictEqual(
    await withDeadline(response.body.text(), 'final response body never settled'),
    ''
  )
  t.strictEqual(count, 3)
})

test('#3975 - keep event loop ticking', async t => {
  const suite = tspl(t, { plan: 2 })

  const res = spawnSync('node', ['./test/fixtures/interceptors/retry-event-loop.js'], {
    stdio: 'pipe'
  })

  const output = res.stderr.toString()
  suite.ok(output.includes('UND_ERR_REQ_RETRY'))
  suite.ok(output.includes('RequestRetryError: Request failed'))
})

